18	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
19	class CommissionPayoutService
20	{
21	    private StripeClient $stripe;
22	
23	    private float $platformFeePercent;
24	
25	    private int $systemHoldDays;
26	
27	    private int $minHoldDays;
28	
29	    private int $gracePeriodDays;
30	
31	    public function __construct(?StripeClient $stripe = null)
32	    {
33	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
34	        $this->platformFeePercent = config('sidest.store.platform_fee_percent', 3);
35	        $this->systemHoldDays = max(0, (int) config('sidest.store.payout_hold_days', 7));
36	        $this->minHoldDays = (int) config('sidest.store.min_payout_hold_days', 7);
37	        // Clamp to [1, 365] — values outside this range produce nonsensical void_at timestamps.
38	        $this->gracePeriodDays = max(1, min(365, (int) config('sidest.store.grace_period_days', 60)));
39	    }
40	
41	    /**
42	     * Main entry point: find all eligible unpaid commissions, batch them,
43	     * and dispatch a per-payout job for each. Returns dispatch counts only —
44	     * actual results are reported per-job via Horizon.
45	     *
46	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
47	     */
48	    public function processEligiblePayouts(): array
49	    {
50	        $stats = [
51	            'batches_dispatched' => 0,
52	            'batches_created' => 0,
53	            'batches_requeued' => 0,
54	        ];
55	
56	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
57	        // resume logic handles collecting/transferring states safely.
58	        $existingPending = CommissionPayout::query()
59	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
60	            ->whereNull('processed_at')
61	            ->where('eligible_after', '<=', now())
62	            ->orderBy('eligible_after')
63	            ->limit(500)
64	            ->get();
65	
66	        foreach ($existingPending as $pendingPayout) {
67	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
68	            $stats['batches_dispatched']++;
69	            $stats['batches_requeued']++;
70	        }
71	
72	        // Find all brands that have unpaid approved accruals, then apply
73	        // per-brand hold days to determine which entries are eligible.
74	        $brandIds = CommissionLedgerEntry::query()
75	            ->whereNull('payout_id')
76	            ->where('entry_type', 'accrual')
77	            ->where('status', 'approved')
78	            ->distinct()
79	            ->pluck('brand_professional_id');
80	
81	        // Pre-load brand store settings for hold-day lookups.
82	        $brandSettings = BrandStoreSettings::query()
83	            ->whereIn('professional_id', $brandIds)
84	            ->pluck('payout_hold_days', 'professional_id');
85	
86	        foreach ($brandIds as $brandId) {
87	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
88	            $cutoff = now()->utc()->subDays($holdDays);
89	
90	            $groups = CommissionLedgerEntry::query()
91	                ->whereNull('payout_id')
92	                ->where('entry_type', 'accrual')
93	                ->where('status', 'approved')
94	                ->where('brand_professional_id', $brandId)
95	                ->where('occurred_at', '<=', $cutoff)
96	                ->select([
97	                    'brand_professional_id',
98	                    'affiliate_professional_id',
99	                    'currency_code',
100	                    DB::raw('SUM(amount_cents) as total_cents'),
101	                    DB::raw('COUNT(*) as entry_count'),
102	                ])
103	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
104	                ->having(DB::raw('SUM(amount_cents)'), '>', 0)
105	                ->get();
106	
107	            foreach ($groups as $group) {
108	                try {
109	                    $payout = $this->createPayoutBatch(
110	                        $group->brand_professional_id,
111	                        $group->affiliate_professional_id,
112	                        $group->currency_code,
113	                        $cutoff,
114	                    );
115	
116	                    if (! $payout) {
117	                        continue;
118	                    }
119	
120	                    $stats['batches_created']++;
121	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
122	                    $stats['batches_dispatched']++;
123	                } catch (\Throwable $e) {
124	                    Log::error('Commission payout batch creation failed', [
125	                        'brand_id' => $group->brand_professional_id,
126	                        'affiliate_id' => $group->affiliate_professional_id,
127	                        'currency' => $group->currency_code,
128	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
129	                    ]);
130	                }
131	            }
132	        }
133	
134	        return $stats;
135	    }
136	
137	    /**
138	     * Resolve the effective hold days for a brand.
139	     * Uses brand override if set, otherwise system default. Always >= system minimum.
140	     */
141	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
142	    {
143	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
144	
145	        return max($this->minHoldDays, $days);
146	    }
147	
148	    /**
149	     * Create a payout batch record and link all eligible ledger entries.
150	     */
151	    private function createPayoutBatch(
152	        string $brandId,
153	        string $affiliateId,
154	        string $currency,
155	        \DateTimeInterface $cutoff,
156	    ): ?CommissionPayout {
157	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
158	            $entries = CommissionLedgerEntry::query()
159	                ->whereNull('payout_id')
160	                ->where('entry_type', 'accrual')
161	                ->where('status', 'approved')
162	                ->where('brand_professional_id', $brandId)
163	                ->where('affiliate_professional_id', $affiliateId)
164	                ->where('currency_code', $currency)
165	                ->where('occurred_at', '<=', $cutoff)
166	                ->lockForUpdate()
167	                ->get();
168	
169	            if ($entries->isEmpty()) {
170	                return null;
171	            }
172	
173	            $grossCents = $entries->sum('amount_cents');
174	            if ($grossCents <= 0) {
175	                return null;
176	            }
177	
178	            // Single locked fetch — reused for both the net-commission sum
179	            // below and the foreach that links these entries to the payout.
180	            // lockForUpdate matches the accrual fetch above and closes the
181	            // race where a reversal could land between SUM and GET.
182	            $reversals = CommissionLedgerEntry::query()
183	                ->whereNull('payout_id')
184	                ->where('entry_type', 'reversal')
185	                ->where('status', 'approved')
186	                ->where('brand_professional_id', $brandId)
187	                ->where('affiliate_professional_id', $affiliateId)
188	                ->where('currency_code', $currency)
189	                ->where('occurred_at', '<=', $cutoff)
190	                ->lockForUpdate()
191	                ->get();
192	
193	            $reversalCents = (int) $reversals->sum('amount_cents');
194	            $netCommission = $grossCents + $reversalCents;
195	            if ($netCommission <= 0) {
196	                return null;
197	            }
198	
199	            $platformFeeCents = (int) round($netCommission * $this->platformFeePercent / 100);
200	            $netPayoutCents = $netCommission - $platformFeeCents;
201	
202	            if ($netPayoutCents <= 0) {
203	                return null;
204	            }
205	
206	            // Per-payout grace window — 60d from creation. If the affiliate
207	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
208	            // cancels this payout and voids its ledger entries.
209	            // grace_period_days lives in config/sidest.php so ops can tune
210	            // the policy without a code release.
211	            $payout = CommissionPayout::forceCreate([
212	                'brand_professional_id' => $brandId,
213	                'affiliate_professional_id' => $affiliateId,
214	                'status' => 'pending',
215	                'gross_commission_cents' => $netCommission,
216	                'platform_fee_cents' => $platformFeeCents,
217	                'net_payout_cents' => $netPayoutCents,
218	                'currency_code' => strtoupper($currency),
219	                'ledger_entry_count' => $entries->count(),
220	                'eligible_after' => $cutoff,
221	                'void_at' => DB::raw("NOW() + INTERVAL '{$this->gracePeriodDays} days'"),
222	                'funding_source' => null,
223	            ]);
224	
225	            foreach ($entries as $entry) {
226	                CommissionPayoutItem::create([
227	                    'payout_id' => $payout->id,
228	                    'commission_ledger_entry_id' => $entry->id,
229	                    'amount_cents' => $entry->amount_cents,
230	                ]);
231	                $entry->forceFill(['payout_id' => $payout->id])->save();
232	            }
233	
234	            foreach ($reversals as $reversal) {
235	                CommissionPayoutItem::create([
236	                    'payout_id' => $payout->id,
237	                    'commission_ledger_entry_id' => $reversal->id,
238	                    'amount_cents' => $reversal->amount_cents,
239	                ]);
240	                $reversal->forceFill(['payout_id' => $payout->id])->save();
241	            }
242	
243	            return $payout;
244	        });
245	    }
246	
247	    /**
248	     * Process a single payout through the full 3-step flow with idempotent resume:
249	     *   1) Debit wallet balance (atomic with status update — crash-safe).
250	     *   2) Charge brand's card for any shortfall.
251	     *   3) Transfer net amount to affiliate via Stripe Connect.
252	     *
253	     * Each step checks the payout's current status before executing, so retries
254	     * (both Horizon automatic and admin manual) resume from where they left off
255	     * rather than restarting from scratch. This prevents double-debiting the wallet
256	     * and double-charging the brand's card.
257	     *
258	     * Return values:
259	     * - true:  completed
260	     * - null:  pending for funding/retry
261	     * - false: failed
262	     */
263	    public function processPayoutBatch(CommissionPayout $payout): ?bool
264	    {
265	        if ($payout->status === 'completed') {
266	            return true;
267	        }
268	
269	        $brand = Professional::find($payout->brand_professional_id);
270	        $affiliate = Professional::find($payout->affiliate_professional_id);
271	
272	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
273	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
274	
275	            return null;
276	        }
277	
278	        if (! $brand) {
279	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
280	
281	            return false;
282	        }
283	
284	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
285	            $this->markPendingFunding(
286	                $payout,
287	                'brand_payment_method_missing',
288	                'No payment method on file. Please add a card in your Stripe settings.',
289	            );
290	
291	            return null;
292	        }
293	
294	        $currencyUpper = strtoupper($payout->currency_code);
295	        $currencyLower = strtolower($currencyUpper);
296	        $amountToCollect = $payout->gross_commission_cents;
297	
298	        // Idempotency key suffix — retry_count is incremented on each admin manual retry
299	        // so fresh Stripe objects are created rather than returning a refunded/failed one
300	        // from within the 24-hour idempotency TTL window.
301	        $retryKey = '_r'.$payout->retry_count;
302	
303	        // Step 1: Wallet debit — or resume from recorded state
304	        //
305	        // The debit and the status update are wrapped in a single DB::transaction
306	        // so a process crash between them can't leave the wallet reduced but the
307	        // payout record still showing 'pending' (which would cause a double-debit on retry).
308	        $walletDebitCents = 0;
309	        $chargeAmountCents = $amountToCollect;
310	
311	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
312	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
313	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
314	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
315	        } else {
316	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents): void {
317	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper);
318	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
319	
320	                $fundingSource = 'card';
321	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
322	                    $fundingSource = 'wallet_and_card';
323	                } elseif ($walletDebitCents > 0) {
324	                    $fundingSource = 'wallet';
325	                }
326	
327	                $payout->forceFill([
328	                    'status' => 'collecting',
329	                    'funding_source' => $fundingSource,
330	                    'wallet_debit_cents' => $walletDebitCents,
331	                    'charge_cents' => $chargeAmountCents,
332	                    'failure_code' => null,
333	                    'failure_reason' => null,
334	                ])->save();
335	            });
336	        }
337	
338	        // Step 2: Charge brand's card for the shortfall (if any)
339	        $latestChargeId = null;
340	
341	        if (in_array($payout->status, ['collected', 'transferring'], true)) {
342	            // PaymentIntent already succeeded in a previous run.
343	            // Retrieve the charge ID so we can use source_transaction on the transfer.
344	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
345	                $pi = $this->stripe->paymentIntents->retrieve($payout->stripe_payment_intent_id);
346	                $latestChargeId = $this->extractLatestChargeId($pi);
347	            }
348	        } elseif ($chargeAmountCents > 0) {
349	            try {
350	                $paymentIntent = $this->stripe->paymentIntents->create([
351	                    'amount' => $chargeAmountCents,
352	                    'currency' => $currencyLower,
353	                    'customer' => $brand->stripe_customer_id,
354	                    'payment_method' => $brand->stripe_payment_method_id,
355	                    'confirm' => true,
356	                    'off_session' => true,
357	                    'description' => "Commission payout #{$payout->id}",
358	                    'metadata' => [
359	                        'sidest_payout_id' => $payout->id,
360	                        'brand_id' => $brand->id,
361	                        'affiliate_id' => $affiliate->id,
362	                    ],
363	                ], ['idempotency_key' => 'pi_'.$payout->id.$retryKey]);
364	
365	                if ($paymentIntent->status !== 'succeeded') {
366	                    // SCA required — cancel the PI so the idempotency key is freed for the next
367	                    // attempt. Without cancellation the same key returns this stuck PI for 24h.
368	                    try {
369	                        $this->stripe->paymentIntents->cancel($paymentIntent->id);
370	                    } catch (\Throwable) {
371	                        // Non-critical: PI may already be in a terminal state
372	                    }
373	                    if ($walletDebitCents > 0) {
374	                        $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
375	                    }
376	                    $this->markPendingFunding($payout, 'charge_requires_action', 'Card charge requires authentication.');
377	
378	                    return null;
379	                }
380	
381	                $latestChargeId = $this->extractLatestChargeId($paymentIntent);
382	
383	                $payout->forceFill([
384	                    'stripe_payment_intent_id' => $paymentIntent->id,
385	                    'status' => 'collected',
386	                ])->save();
387	            } catch (ApiConnectionException|RateLimitException $e) {
388	                // Transient error — re-throw so Horizon retries with backoff.
389	                // Wallet debit is already committed in 'collecting' status; the
390	                // idempotent resume will skip re-debiting on the next attempt.
391	                throw $e;
392	            } catch (ApiErrorException $e) {
393	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
394	                if ($walletDebitCents > 0) {
395	                    $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
396	                }
397	                $this->markPendingFunding($payout, 'charge_failed', $e->getStripeCode() ?? 'stripe_error');
398	
399	                return null;
400	            }
401	        } else {
402	            // Fully funded by wallet — only advance status if not already past this step
403	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
404	                $payout->forceFill(['status' => 'collected'])->save();
405	            }
406	        }
407	
408	        // Step 3: Transfer net amount to the affiliate's Connect account
409	        try {
410	            if ($payout->status !== 'transferring') {
411	                $payout->forceFill(['status' => 'transferring'])->save();
412	            }
413	
414	            $transferPayload = [
415	                'amount' => $payout->net_payout_cents,
416	                'currency' => $currencyLower,
417	                'destination' => $affiliate->stripe_connect_account_id,
418	                'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
419	                'metadata' => [
420	                    'sidest_payout_id' => $payout->id,
421	                    'brand_id' => $brand->id,
422	                    'affiliate_id' => $affiliate->id,
423	                ],
424	            ];
425	
426	            if ($latestChargeId) {
427	                $transferPayload['source_transaction'] = $latestChargeId;
428	            }
429	
430	            $transfer = $this->stripe->transfers->create(
431	                $transferPayload,
432	                ['idempotency_key' => 'tr_'.$payout->id.$retryKey]
433	            );
434	
435	            $payout->forceFill([
436	                'stripe_transfer_id' => $transfer->id,
437	                'status' => 'completed',
438	                'processed_at' => now(),
439	                'failure_code' => null,
440	                'failure_reason' => null,
441	            ])->save();
442	
443	            Log::info('Commission payout completed', [
444	                'payout_id' => $payout->id,
445	                'gross_cents' => $payout->gross_commission_cents,
446	                'wallet_debit_cents' => $walletDebitCents,
447	                'charge_cents' => $chargeAmountCents,
448	                'platform_fee_cents' => $payout->platform_fee_cents,
449	                'net_cents' => $payout->net_payout_cents,
450	                'funding_source' => $payout->funding_source,
451	                'currency' => $payout->currency_code,
452	            ]);
453	
454	            // Rebuild commerce aggregates so commission_paid_cents is reflected.
455	            // Guard against null FKs (SET NULL on professional hard-delete).
456	            if ($payout->brand_professional_id && $payout->affiliate_professional_id) {
457	                \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
458	                    (string) $payout->brand_professional_id,
459	                    (string) $payout->affiliate_professional_id,
460	                    now()->toDateString()
461	                );
462	            }
463	
464	            return true;
465	        } catch (ApiConnectionException|RateLimitException $e) {
466	            // Transient error — re-throw so Horizon retries from 'transferring' status.
467	            // Wallet and charge are NOT reversed: if the transfer succeeded on Stripe's side
468	            // but the response was lost in transit, the idempotency key returns the same
469	            // transfer on retry rather than creating a duplicate.
470	            throw $e;
471	        } catch (ApiErrorException $e) {
472	            // Terminal transfer failure — credit wallet back, then attempt to auto-refund.
473	            if ($walletDebitCents > 0) {
474	                $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
475	            }
476	
477	            $failureCode = 'transfer_failed';
478	
479	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
480	                try {
481	                    $this->stripe->refunds->create([
482	                        'payment_intent' => $payout->stripe_payment_intent_id,
483	                    ], ['idempotency_key' => "rf_{$payout->id}_{$payout->stripe_payment_intent_id}"]);
484	                    $failureCode = 'transfer_failed_refunded';
485	                    // Clear PI ID so an admin retry can create a fresh PaymentIntent
486	                    // (same idempotency key within 24h would return the now-refunded PI).
487	                    $payout->forceFill(['stripe_payment_intent_id' => null])->save();
488	                } catch (\Throwable $refundEx) {
489	                    // Auto-refund failed — the brand may still be charged. Flag for manual resolution.
490	                    $failureCode = 'transfer_failed_refund_needed';
491	                    $payout->forceFill(['needs_manual_refund' => true])->save();
492	                    Log::error('Auto-refund after transfer failure failed — manual action required', [
493	                        'payout_id' => $payout->id,
494	                        'payment_intent_id' => $payout->stripe_payment_intent_id,
495	                        'transfer_error' => $e->getStripeCode() ?? 'stripe_error',
496	                        'refund_error' => $refundEx instanceof ApiErrorException ? ($refundEx->getStripeCode() ?? 'stripe_error') : get_class($refundEx),
497	                    ]);
498	                }
499	            }
500	
501	            $this->failPayout($payout, $failureCode, $e->getStripeCode() ?? 'stripe_error');
502	
503	            return false;
504	        }
505	    }
506	
507	    /**
508	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
509	     * Returns the actual amount debited (0 if no balance available).
510	     */
511	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode): int
512	    {
513	        if ($requestedCents <= 0) {
514	            return 0;
515	        }
516	
517	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode) {
518	            $brand = Professional::query()
519	                ->whereKey($brandId)
520	                ->lockForUpdate()
521	                ->first();
522	
523	            if (! $brand) {
524	                return 0;
525	            }
526	
527	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
528	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
529	
530	            if ($walletCurrency !== strtoupper($currencyCode) || $balance <= 0) {
531	                return 0;
532	            }
533	
534	            $debit = min($balance, $requestedCents);
535	            $brand->stripe_manual_balance_cents = $balance - $debit;
536	            $brand->save();
537	
538	            return $debit;
539	        });
540	    }
541	
542	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
543	    {
544	        if ($amountCents <= 0) {
545	            return;
546	        }
547	
548	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
549	            $brand = Professional::query()
550	                ->whereKey($brandId)
551	                ->lockForUpdate()
552	                ->first();
553	
554	            if (! $brand) {
555	                return;
556	            }
557	
558	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
559	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
560	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
561	            $brand->save();
562	        });
563	    }
564	
565	    private function extractLatestChargeId(object $paymentIntent): ?string
566	    {
567	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
568	            return $paymentIntent->latest_charge;
569	        }
570	
571	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
572	            return $paymentIntent->latest_charge->id;
573	        }
574	
575	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
576	            foreach ($paymentIntent->charges->data as $charge) {
577	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
578	                    return $charge->id;
579	                }
580	            }
581	        }
582	
583	        return null;
584	    }
585	
586	    private function markPendingFunding(CommissionPayout $payout, string $code, string $reason): void
587	    {
588	        $payout->forceFill([
589	            'status' => 'pending_funds',
590	            'failure_code' => $code,
591	            'failure_reason' => $reason,
592	            'processed_at' => null,
593	        ])->save();
594	
595	        Log::notice('Commission payout pending funding', [
596	            'payout_id' => $payout->id,
597	            'code' => $code,
598	            'reason' => $reason,
599	        ]);
600	    }
601	
602	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
603	    {
604	        $payout->forceFill([
605	            'status' => 'failed',
606	            'failure_code' => $code,
607	            'failure_reason' => $reason,
608	        ])->save();
609	
610	        Log::warning('Commission payout failed', [
611	            'payout_id' => $payout->id,
612	            'code' => $code,
613	            'reason' => $reason,
614	        ]);
615	    }
616	
617	    /**
618	     * Manually retry a stuck payout batch (admin endpoint).
619	     *
620	     * Increments retry_count so a fresh Stripe idempotency key is used —
621	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
622	     *
623	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
624	     * the brand may still be charged. Manual verification is required before retrying.
625	     *
626	     * Runs synchronously so the admin sees the result immediately.
627	     */
628	    public function retryPayout(CommissionPayout $payout): bool
629	    {
630	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
631	            return false;
632	        }
633	
634	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
635	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
636	            return false;
637	        }
638	
639	        // If the wallet was already debited in a previous run, resume from 'collecting'
640	        // so processPayoutBatch() enters its idempotent resume branch and skips
641	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
642	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
643	
644	        $payout->forceFill([
645	            'status' => $resumeStatus,
646	            'failure_code' => null,
647	            'failure_reason' => null,
648	            'needs_manual_refund' => false,
649	            'retry_count' => ($payout->retry_count ?? 0) + 1,
650	        ])->save();
651	
652	        return $this->processPayoutBatch($payout) === true;
653	    }
654	
655	    /**
656	     * Get payout summary for a professional (as brand or affiliate).
657	     */
658	    public function getPayoutSummary(Professional $professional): array
659	    {
660	        $asBrand = CommissionPayout::query()
661	            ->where('brand_professional_id', $professional->id)
662	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
663	            ->groupBy('status')
664	            ->get()
665	            ->keyBy('status');
666	
667	        $asAffiliate = CommissionPayout::query()
668	            ->where('affiliate_professional_id', $professional->id)
669	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
670	            ->groupBy('status')
671	            ->get()
672	            ->keyBy('status');
673	
674	        return [
675	            'as_brand' => $asBrand,
676	            'as_affiliate' => $asAffiliate,
677	        ];
678	    }
679	}
